items[0]=(items[0][0],items[0][1].replace('GET /orders security','GET /orders/{order_id} security')+"\nSupplied operation requirement table: "+json.dumps(f['operation_requirements'])+"\nCandidate generated components.securitySchemes: "+json.dumps({**f['bearer_scheme'],**f['authorization_code_scheme']})+"\nCandidate operation.security (same credential authority): GET /orders/{order_id} -> [{'OrderBearer':[], 'OrderAuthorizationCode':['orders:read']}]; POST /orders -> [{'OrderBearer':[], 'OrderAuthorizationCode':['orders:write']}].\nReview each protected operation against read_orders/write_orders dependencies; these declarations do not add an independently accepted credential.",items[0][2]);C[c]=(p,items)

c='fastapi.openapi_contract_inspection';ff=files(c);schema=json.loads(ff['generated_schema.json']);http=json.loads(ff['http_evidence.json']);security=json.loads(ff['security_configuration.json'])
classify(c,'Audit the supplied fictional orders router. Each excerpt quotes registry contract artifacts or captured non-auth HTTP evidence and a proposed review conclusion. Judge whether that conclusion is supported. This audit does not add authentication/authorization HTTP tests.',[
 ('good','GET /openapi.json selected paths and parameters: '+json.dumps({p:{method:{k:o[k] for k in ['parameters','requestBody'] if k in o} for method,o in operations.items()} for p,operations in schema['paths'].items()})+'\nExecutable model excerpt:\n'+ff['models.py']+'\nGenerated request/public schemas: '+json.dumps({k:schema['components']['schemas'][k] for k in ['OrderInput','PublicOrder','ErrorBody']})+'\nCaptured non-auth HTTP evidence: '+json.dumps(http['records'])+'\nProposed review: inventory both router paths and path parameters; id is required, integer and >0 for creation while status has the declared default/enum; captured negative-id request is rejected; successful public projections contain only id/status. No requiredness or output-field drift is shown by this packet. Compare every declared type/constraint/output field, rather than inferring behavior from schema text alone.','The review distinguishes input declarations and captured validation/output evidence without fabricating a drift finding.'),
 ('good','POST /orders generated response declarations: '+json.dumps(schema['paths']['/orders']['post']['responses'])+'\nCaptured duplicate request and emitted outcome: '+json.dumps(next(r for r in http['records'] if r['request'].get('json',{}).get('id')==fixture(c)['initial_orders'][0]['id']))+'\nProposed finding: duplicate handling emits 400 while the additional documented duplicate outcome is 409; the declaration alone does not prove 409 emission. Check the description and ErrorBody schema against this exact outcome.','The duplicate HTTP status conflicts with its declared status; safe body agreement does not erase the status mismatch.'),
 ('good','Generated security scheme and operation entries: '+json.dumps({'schemes':schema['components']['securitySchemes'],'operations':{p:{m:o.get('security') for m,o in operations.items()} for p,operations in schema['paths'].items()}})+'\nEstablished configured acquisition/security contract: '+json.dumps({k:security[k] for k in ['schemes','operations','operation_dependencies']})+'\nProposed finding: generated output omits the configured authorization-code acquisition scheme and the declared operation scope requirements. Compare configured issuer URLs and scope descriptions with every operation; do not invent a password grant and do not add new HTTP authentication tests here.','The public security declarations are incomplete relative to the established configuration; this conclusion is a contract audit, not a new authentication test.'),
 ('good','Generated public examples: '+json.dumps(schema['components']['schemas']['PublicOrder']['examples'])+'\nCandidate audit code:\nfor example in schema["components"]["schemas"]["PublicOrder"]["examples"]:\n    PublicOrder.model_validate(example)\n    assert set(example) == {"id","status"}\n# Inspect response descriptions and all published examples for sensitive fields. The supplied fictional example validates and contains only the public projection. Do not label it a secret leak without evidence.','Example validation and sensitive-field inspection belong in the audit; this concrete public example is valid and contains no credential.'),
 ('bad','POST /orders generated duplicate entry: '+json.dumps(schema['paths']['/orders']['post']['responses']['409'])+'\nCaptured duplicate outcome: '+json.dumps(next(r for r in http['records'] if r['request'].get('json',{}).get('id')==fixture(c)['initial_orders'][0]['id']))+'\nProposed conclusion: the presence of 409 proves the endpoint returned 409, so no mismatch exists. Skip public examples and operation security because they cannot affect the audit.','The quoted captured outcome disproves the claimed emission, and examples/security remain contract-audit dimensions.')])
